function extract(raw, memory, info) {
  raw = raw || {}; memory = memory || {}; info = info || {};
  var TICK = 16, G = 0.25, JUMP = -4.6, OFF = 12, PAD = 2, BIG = 1e9, DEAD = -1e9;
  var H = 60, CG = 190, S_UP = 1, S_DN = 1.2, SOFT = 10, SOFTPAD = 20, DISC = 0.05, AIM = 16, BUDGET = 12000, BUDGET_ANY = 20000;
  var M_IN = 0.5, M_OUT = 0.5, WMIN = 17 - 4 * Math.sin(1);
  var i, j, k, n;
  function isNum(a) { return typeof a === 'number' && isFinite(a); }
  function num(a, d) { return isNum(a) ? a : d; }
  // tilted bird: [half height of the rotated box (ground test), half height and half width of the game's reduced hitbox (pipe test)]
  function boxOf(v) {
    var r = Math.abs(Math.min(v / 10 * 90, 90)), a = r * Math.PI / 180;
    var bh = 34 * Math.sin(a) + 24 * Math.cos(a);
    return [bh / 2, (24 + bh) / 4, 17 - 4 * Math.sin(r / 90)];
  }
  var screen = num(raw.screen, -1);
  var ground = num(raw.ground, num(raw.height, 420));
  var bird = raw.bird || {};
  // the bird never moves sideways: average its centre to remove the rounding of its box
  var cx = num(bird.x, 59) + num(bird.w, 36) / 2, cxm = memory.cxN >= 5 ? memory.cxS / memory.cxN : null;
  if (screen === 1 && isNum(bird.x) && isNum(bird.w) && (cxm === null || Math.abs(cx - cxm) < 3)) {
    memory.cxS = (memory.cxS || 0) + cx; memory.cxN = (memory.cxN || 0) + 1;
    if (cxm !== null) cx = memory.cxS / memory.cxN;
  }
  var BL = cx - 17, BR = cx + 17;
  var top = num(raw.top, num(bird.y, 200));
  var v0 = num(raw.velocity, 0);
  var lag = Math.max(0, num(info.lagMs, 0));
  var now = isNum(info.nowMs) ? info.nowMs : (isNum(memory.lastNow) ? memory.lastNow + TICK : 0);
  var live = screen === 1 && memory.lastScreen === 1 && isNum(memory.lastNow) && now > memory.lastNow;
  // no game frame ran since the last decision (the game's 16.7 ms timer skips about one 16 ms tick in 25)
  var skip = screen === 1 && memory.lastScreen === 1 && v0 === memory.lastV && top === memory.lastTop;

  // game frame length: whole gravity steps (+0.25 each) over flap-free intervals, counting intervals with no frame
  if (live && isNum(memory.lastV) && now - memory.lastNow <= 400) {
    var frf = (v0 - memory.lastV) / G, fr = Math.round(frf);
    if (memory.lastV > -3.5 && v0 > -4 && fr >= 0 && Math.abs(frf - fr) < 0.2) {
      memory.fT = (memory.fT || 0) + now - memory.lastNow; memory.fN = (memory.fN || 0) + fr;
    }
  }
  var FRAME = memory.fN >= 30 ? Math.min(18, Math.max(15, memory.fT / memory.fN)) : 1000 / 60;
  // decision cadence: game time between the frames the engine decides on; the next decision's flap lands one cadence after this one's
  if (live) {
    var dtD = Math.min(150, Math.max(TICK, now - memory.lastNow));
    memory.dI = isNum(memory.dI) ? 0.75 * memory.dI + 0.25 * dtD : dtD;
  }
  var DEC = isNum(memory.dI) ? memory.dI : Math.max(TICK, lag);

  var pipes = [], odd = [], list = Array.isArray(raw.pipes) ? raw.pipes : [];
  for (i = 0; i < list.length; i++) {
    var p = list[i];
    if (!p || !isNum(p.x)) continue;
    if (isNum(p.gapTop) && isNum(p.gapBottom)) pipes.push({ x: p.x, w: num(p.w, 52), gt: p.gapTop, gb: p.gapBottom });
    else odd.push({ kind: 'pipe', x: p.x, y: num(p.y, 0), w: num(p.w, 52), h: num(p.h, ground) });
  }
  var known = { screen: 1, bird: 1, top: 1, velocity: 1, ground: 1, width: 1, height: 1, pipes: 1 };
  for (var key in raw) {
    if (known[key] || /cloud|star|score|digit|decor|sky|back|text|label|title|medal|best/i.test(key)) continue;
    var val = raw[key], arr = Array.isArray(val) ? val : (val && typeof val === 'object' ? [val] : []);
    for (i = 0; i < arr.length && i < 20; i++) {
      var o = arr[i];
      if (o && typeof o === 'object' && isNum(o.x)) odd.push({ kind: key, x: o.x, y: num(o.y, 0), w: num(o.w, num(o.width, 0)), h: num(o.h, num(o.height, 0)) });
    }
  }
  var unk = null, unkN = 0;
  for (i = 0; i < odd.length; i++) {
    if (odd[i].x + odd[i].w < BL) continue;
    unkN++;
    if (!unk || odd[i].x < unk.x) unk = odd[i];
  }
  pipes.sort(function (a, b) { return a.x - b.x; });
  // a pipe stays in play a little past the bird's tail: the game drops it only a frame after the bird has cleared it
  var ahead = [];
  for (i = 0; i < pipes.length; i++) if (pipes[i].x + pipes[i].w + 4 >= BL) ahead.push(pipes[i]);
  var lead = ahead[0], sec = ahead[1];

  // pipe speed (px/ms), measured on the leading pipe
  var speed = isNum(memory.speed) ? memory.speed : 1000 / 7500;
  if (screen === 1 && lead) {
    var tr = memory.track;
    if (tr && tr.gt === lead.gt && tr.gb === lead.gb && lead.x <= tr.x + 1 && now >= tr.t) {
      if (now - tr.t >= 200) { var sp = (tr.x - lead.x) / (now - tr.t); if (sp > 0.03 && sp < 0.6) speed = sp; }
    } else memory.track = { gt: lead.gt, gb: lead.gb, x: lead.x, t: now };
  } else if (screen !== 1) memory.track = null;
  memory.speed = speed;

  // lookahead: memoised search over the frames a flap can land on, max-min clearance
  var hT = [], hB = [], nI = [], nO = [], sT = [], sB = [], tg = [], FA = [], EA = [], WA = [], FB = [], EB = [], WB = [];
  var memo = {}, steps = 0, budget = BUDGET, enough = CG, grid = [];
  function clr(j, cy, e, fh, w) {
    var c = ground - cy - fh;
    if (c <= 0) return DEAD;
    var bt = cy - e, bb = cy + e, x;
    // the pipe is tested once the hitbox (half width w) reaches past its left edge, until a frame after it is past its right edge
    if (hT[j] > -BIG && w > nI[j] && w >= nO[j]) {
      x = bt - hT[j]; if (x <= 0) return DEAD; if (x < c) c = x;
      x = hB[j] - bb; if (x <= 0) return DEAD; if (x < c) c = x;
    }
    x = Math.min(bt - sT[j], sB[j] - bb) + SOFTPAD;
    if (x < c) c = x;
    c += DISC * j;
    return c > CG ? CG : (c < -150 ? -150 : c);
  }
  function run(f, y, flap) {
    var E = flap ? EB : EA, Fh = flap ? FB : FA, W = flap ? WB : WA, base = flap ? JUMP : v0;
    var cj = [], cy = [], cm = [], cs = [], m = BIG, dead = 0, yy = y, jj, nn, vv, c, a, b;
    for (jj = f + 1; jj <= H; jj++) {
      nn = flap ? jj - f : jj; vv = base + G * nn; yy += vv; steps++;
      c = clr(jj, yy + OFF, E[nn], Fh[nn], W[nn]);
      if (c === DEAD) { dead = jj; break; }
      if (c < m) m = c;
      if (yy + OFF - E[nn] <= 0) yy = 0;
      if (grid[jj] === true) { cj.push(jj); cy.push(yy); cm.push(m); cs.push(Math.abs(yy + OFF - tg[jj + 1] - AIM) + (vv < 0 ? 60 : 0)); }
    }
    var best = dead ? dead - 300 : (m >= BIG ? CG : m), ord = [];
    for (a = 0; a < cj.length; a++) ord.push(a);
    ord.sort(function (p1, p2) { return cs[p1] - cs[p2]; });
    for (b = 0; b < ord.length && best < enough && steps <= budget; b++) {
      a = ord[b];
      if (cm[a] <= best) continue;
      c = V(cj[a], cy[a]);
      if (c > cm[a]) c = cm[a];
      if (c > best) best = c;
    }
    return best;
  }
  function V(f, y) {
    var mk = f * 4096 + Math.round(y) + 1024, r = memo[mk];
    if (r === undefined) { r = run(f, y, true); memo[mk] = r; }
    return r;
  }
  // frames 1..f0 run before this decision's flap can land; then the flap acts from frame f0 + 1 (flap) or not at all (wait)
  function roots(f0) {
    var y = top, mPre = BIG, c, q, a, b;
    for (q = 1; q <= f0; q++) {
      y += v0 + G * q;
      c = clr(q, y + OFF, EA[q], FA[q], WA[q]);
      if (c === DEAD) return [q - 300, q - 300];
      if (c < mPre) mPre = c;
      if (y + OFF - EA[q] <= 0) y = 0;
    }
    memo = {};
    steps = 0; a = Math.min(mPre, V(f0, y));
    steps = 0; b = Math.min(mPre, run(f0, y, false));
    return [a, b];
  }

  var mF = 0, mW = 0, lF = 0, lW = 0, dieF = false, dieW = false;
  if (screen === 1) {
    try {
      var nA = Math.min(ahead.length, 4);
      for (j = 0; j <= H; j++) {
        // the game reads pipe positions from the last 16 ms page frame: entry is tested with the pipe half a frame on,
        // removal with the pipe where it was one frame earlier (two after a skipped tick)
        var tIn = (j - 0.5) * FRAME, tOut = ((j === 1 && skip) ? -2 : j - 2) * FRAME;
        var ht = -BIG, hb = BIG, ni = BIG, no = BIG, st = -BIG, sb = BIG, first = true;
        for (i = 0; i < nA; i++) {
          var q = ahead[i], eOut = q.x - speed * tOut + q.w - PAD + M_OUT, eIn = q.x - speed * tIn - PAD - M_IN;
          if (eOut < BL) continue;
          if (first) {
            first = false;
            if (eIn < BR) { ht = q.gt; hb = q.gb; ni = eIn - cx; no = cx - eOut; if (ni < WMIN) continue; }
          }
          var d = Math.max(0, eIn - BR);
          st = Math.max(st, q.gt - S_UP * d - SOFT);
          sb = Math.min(sb, q.gb + S_DN * d + SOFT);
        }
        hT.push(ht); hB.push(hb); nI.push(ni); nO.push(no); sT.push(st); sB.push(sb);
        tg.push(ht > -BIG ? (ht + hb) / 2 : (st > -BIG ? (Math.max(st, 40) + Math.min(sb, ground - 40)) / 2 : ground - 200));
      }
      for (n = 0; n <= H + 1; n++) {
        var ba = boxOf(v0 + G * n), bf = boxOf(JUMP + G * n);
        FA.push(ba[0]); EA.push(ba[1]); WA.push(ba[2]); FB.push(bf[0]); EB.push(bf[1]); WB.push(bf[2]);
      }
      // a flap lands lagMs after its frame and the next decision's flap one cadence later, so flaps can only land on that grid;
      // each landing is known to +-1 frame: both phases are searched, the margins keep the worse, the tie-break the better
      var xL = lag / FRAME, dF = lag > 0 ? Math.max(1, DEC / FRAME) : 1, ph, g, rr;
      mF = BIG; mW = BIG; lF = -BIG; lW = -BIG;
      for (ph = 0; ph < (lag > 0 ? 2 : 1); ph++) {
        grid = [];
        for (k = 1; k < 100; k++) { g = Math.floor(xL + k * dF) + ph; if (g >= H) break; grid[g] = true; }
        if (dF < 2) for (j = 11; j < H; j++) if (j <= 30 ? j % 2 : j % 3) grid[j] = false;
        budget = BUDGET; enough = CG;
        rr = roots(Math.min(20, Math.floor(xL) + ph));
        mF = Math.min(mF, rr[0]); mW = Math.min(mW, rr[1]); lF = Math.max(lF, rr[0]); lW = Math.max(lW, rr[1]);
      }
      // a certain crash: no way through even if every later flap could land on any frame
      dieF = mF < -200; dieW = mW < -200;
      if (dieF || dieW) {
        grid = [];
        for (j = 1; j < H; j++) grid[j] = j <= 10 || (j <= 30 ? j % 2 === 0 : j % 3 === 0);
        budget = BUDGET_ANY; enough = -200;
        rr = roots(lag > 0 ? Math.min(20, Math.round(lag / FRAME)) : 0);
        dieF = dieF && rr[0] < -200; dieW = dieW && rr[1] < -200;
      }
    } catch (err) { mF = 0; mW = 0; lF = 0; lW = 0; dieF = false; dieW = false; }
  }

  var b0 = boxOf(v0), cy0 = top + OFF, bt0 = cy0 - b0[1], bb0 = cy0 + b0[1];
  var rF = Math.round(mF), rW = Math.round(mW), dl = lF - lW;
  memory.lastNow = now; memory.lastV = v0; memory.lastTop = top; memory.lastScreen = screen;
  return {
    over: screen === 2,
    playing: screen === 1,
    birdY: Math.round(cy0),
    vel: Math.round(v0 * 10) / 10,
    roomToGround: Math.round(ground - cy0 - b0[0]),
    pipeDx: lead ? Math.round(lead.x - BR) : null,
    inPipe: lead ? lead.x - PAD < BR : false,
    roomAbove: lead ? Math.round(bt0 - lead.gt) : null,
    roomBelow: lead ? Math.round(lead.gb - bb0) : null,
    msToPipe: lead ? Math.round(Math.max(0, lead.x - PAD - BR) / speed) : null,
    msToClear: lead ? Math.round(Math.max(0, lead.x + lead.w - PAD - BL) / speed) : null,
    nextGapShift: lead && sec ? Math.round((sec.gt + sec.gb - lead.gt - lead.gb) / 2) : null,
    marginIfFlap: rF,
    marginIfWait: rW,
    flapEffect: screen !== 1 ? 'same' : (rF > rW ? 'moreRoom' : (rF < rW ? 'lessRoom' : (dl > 0.5 ? 'moreRoom' : (dl < -0.5 ? 'lessRoom' : 'same')))),
    crashIfFlap: screen === 1 && dieF,
    crashIfWait: screen === 1 && dieW,
    unknownThing: unk ? { kind: String(unk.kind).slice(0, 16), dx: Math.round(unk.x - BR), y: Math.round(unk.y), w: Math.round(unk.w), h: Math.round(unk.h), count: unkN } : null
  };
}

teacher:
function teach(state) {
  if (!state || state.over) return 'wait';
  if (!state.playing) return 'flap';
  return state.flapEffect === 'moreRoom' ? 'flap' : 'wait';
}
